private string LegendTongKetToHTML(bool bolHe4)
{
    if (bolHe4)
        return "";

    int intRowsPerCol = 5;
    int intSubjectCount = dtbClassSubject.Rows.Count;
    int intColCount = (intSubjectCount + intRowsPerCol - 1) / intRowsPerCol;

    string[] arrCodes = new string[intSubjectCount];
    string[] arrNames = new string[intSubjectCount];
    int intIndex = 1;
    foreach (DataRow drwSubject in dtbClassSubject.Rows)
    {
        arrCodes[intIndex - 1] = GetTongKetSubjectCode(intIndex);
        string strName = drwSubject["SubjectName"].ToString();
        if (strName == "")
            strName = "&nbsp;";
        arrNames[intIndex - 1] = strName;
        intIndex++;
    }

    string strRows = "";
    for (int r = 0; r < intRowsPerCol; r++)
    {
        string strRow = "<tr>";
        for (int c = 0; c < intColCount; c++)
        {
            int intSubjIdx = c * intRowsPerCol + r;
            if (intSubjIdx < intSubjectCount)
            {
                strRow += "<td class='code'>" + arrCodes[intSubjIdx] + "</td>"
                    + "<td class='colon'>:</td>"
                    + "<td class='name'>" + arrNames[intSubjIdx] + "</td>";
            }
            else
            {
                strRow += "<td class='code'>&nbsp;</td>"
                    + "<td class='colon'>&nbsp;</td>"
                    + "<td class='name'>&nbsp;</td>";
            }

            if (c < intColCount - 1)
                strRow += "<td class='spacer'>&nbsp;</td><td class='spacer'>&nbsp;</td>";
        }
        strRow += "</tr>";
        strRows += strRow;
    }

    return "<div class='legend'><table class='legend-cols'>" + strRows + "</table></div>";
}

